void push(int v) {
  TaggedPointer old_top = top.load();
  Node* n = new Node{v, old_top.ptr};
  TaggedPointer new_top{ n, old_top.tag + 1 };
  while (!top.compare_exchange_weak(old_top, new_top));
}

int pop() {
  TaggedPointer old_top = top.load();
  while (old_top.ptr && !top.compare_exchange_weak(old_top, {old_top.ptr->next, old_top.tag + 1}));
  return old_top.ptr ? old_top.ptr->val : -1;
}
```

This fix ensures that each modification of the stack top is uniquely identified by its tag, preventing the ABA problem from occurring.

